// still refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught again from
// the constraint itself), or, when askReferrers, a referrer in another
// database or service (r.Refs). A purge never fails, and never cascades,
// because of a referrer. gorm.ErrRecordNotFound when there is no such row.
func (r *GormStatisticReportRepository) purge(ctx context.Context, db *gorm.DB, key, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/StatisticReport", name) {
		return true, nil
	}
	// A savepoint inside a caller's transaction: a foreign key the query
	// above does not know (one from another generator run) rolls back only
	// this purge.
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		return r.purgeTx(ctx, tx, key)
	})
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GormStatisticReportRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, r.DB, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			key, err := r.rowKey(m.GetName())
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, r.DB, key, m.GetName(), true)
			switch {
			case errors.Is(err, gorm.ErrRecordNotFound):
			case err != nil:
				return res, repox.MapGormErr(err)
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GormStatisticReportRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*statistic_reportv1.StatisticReport, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*statistic_reportv1.StatisticReport, string, error) {
		return r.List(ctx, "hotels/-", in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ StatisticReportRepository = (*GormStatisticReportRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreateStatisticReport queues a create and returns the name the record will have.
func (b *gormBatch) CreateStatisticReport(parent string, in *statistic_reportv1.StatisticReport) (string, error) {
	r := &GormStatisticReportRepository{DB: b.db}
	m, named, err := r.newRow(parent, in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queueStatisticReportReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateStatisticReport queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdateStatisticReport(in *statistic_reportv1.StatisticReport, paths []string) {
	r := &GormStatisticReportRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueStatisticReportReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getStatisticReport)})
}

// UpdateStatisticReportWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it, and a guard that fails rolls the whole batch back.
func (b *gormBatch) UpdateStatisticReportWithOutputOnly(in *statistic_reportv1.StatisticReport, paths, outputPaths []string) {
	r := &GormStatisticReportRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueStatisticReportReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getStatisticReport)})
}

// UpdateStatisticReportOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards it.
func (b *gormBatch) UpdateStatisticReportOutputOnly(in *statistic_reportv1.StatisticReport, paths []string) {
	r := &GormStatisticReportRepository{DB: b.db}
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateOutputOnlyTx(ctx, tx, in, paths)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getStatisticReport)})
}

// DeleteStatisticReport queues a soft delete. A record already deleted or gone is
// not an error: two batches deleting the same record must not fail each other.
func (b *gormBatch) DeleteStatisticReport(name string) {
	r := &GormStatisticReportRepository{DB: b.db, Retention: b.retention}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueStatisticReportDelete(b.u, name, false)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.markDeleted(ctx, tx, key).Error
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getStatisticReport)})
}

// PurgeStatisticReport queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) PurgeStatisticReport(name string) {
	// A record something still refers to is kept, as Purge keeps it.
	r := &GormStatisticReportRepository{DB: b.db, Refs: b.u.Conn().References}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	keep := queueStatisticReportPurge(b.u, name)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		if *keep {
			return nil
		}
		if _, err := r.purge(ctx, tx, key, name, false); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}
		return nil
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/StatisticReport", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getStatisticReport)})
}
